#!/usr/bin/env python3
"""Print the top N most frequent words in a text file."""

import argparse
import re
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the top N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the input text file")
    parser.add_argument(
        "top_n",
        type=int,
        help="Number of top frequent words to display",
    )
    return parser.parse_args()


def read_words(file_path):
    with open(file_path, "r", encoding="utf-8") as file_handle:
        raw_text = file_handle.read()
    word_list = re.findall(r"[a-zA-Z]+", raw_text.lower())
    return word_list


def count_words(word_list):
    word_counts = Counter(word_list)
    return word_counts


def get_top_words(word_counts, top_n):
    top_word_list = word_counts.most_common(top_n)
    return top_word_list


def print_results(top_word_list):
    for word, count in top_word_list:
        print(f"{word}: {count}")


def main():
    args = parse_args()
    word_list = read_words(args.filename)
    word_counts = count_words(word_list)
    top_word_list = get_top_words(word_counts, args.top_n)
    print_results(top_word_list)


if __name__ == "__main__":
    main()

