import argparse
import re
from collections import Counter


def read_words(filename):
    return [re.sub(r"[^\w]", "", w).lower() for line in open(filename) for w in line.split()]


def filter_words(words):
    return [w for w in words if w]


def count_words(words):
    return Counter(words)


def top_n_words(counter, n):
    return counter.most_common(n)


def format_output(pairs):
    return "\n".join(f"{word}\t{count}" for word, count in pairs)


def build_parser():
    return (lambda p: (p.add_argument("filename"), p.add_argument("-n", "--top-n", type=int, default=10, dest="top_n")) or p)(argparse.ArgumentParser(description="Print top N most frequent words in a file."))


def main():
    return print(format_output(top_n_words(count_words(filter_words(read_words(build_parser().parse_args().filename))), build_parser().parse_args().top_n)))


if __name__ == "__main__":
    main()

