from typing import Any

from fastapi import FastAPI, HTTPException, Request
from pydantic import BaseModel


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.store = {}
    yield
    app.state.store.clear()


app = FastAPI(lifespan=lifespan)


class ValuePayload(BaseModel):
    value: Any


def get_store(request: Request) -> dict:
    return request.app.state.store


@app.get("/items")
def list_items(request: Request):
    store = get_store(request)
    return store


@app.get("/items/{key}")
def get_item(key: str, request: Request):
    store = get_store(request)
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    return {"key": key, "value": store[key]}


@app.put("/items/{key}", status_code=200)
def put_item(key: str, payload: ValuePayload, request: Request):
    store = get_store(request)
    store[key] = payload.value
    return {"key": key, "value": store[key]}


@app.delete("/items/{key}", status_code=200)
def delete_item(key: str, request: Request):
    store = get_store(request)
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    del store[key]
    return {"deleted": key}

