import argparse
import string
import sys
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file to analyze")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def read_words(filename):
    try:
        with open(filename, "r", encoding="utf-8") as file_handle:
            raw_text = file_handle.read()
    except FileNotFoundError:
        print(f"Error: file '{filename}' not found.", file=sys.stderr)
        sys.exit(1)

    translator = str.maketrans("", "", string.punctuation)
    cleaned_text = raw_text.translate(translator)
    word_list = cleaned_text.lower().split()
    return word_list


def count_words(word_list):
    word_counts = Counter(word_list)
    return word_counts


def print_top_words(word_counts, n):
    unique_word_count = len(word_counts)
    top_n = min(n, unique_word_count)
    if top_n < n:
        print(
            f"Note: only {unique_word_count} unique word(s) found; "
            f"showing all {unique_word_count}.",
            file=sys.stderr,
        )
    for word, count in word_counts.most_common(top_n):
        print(f"{word}: {count}")


def main():
    args = parse_args()
    word_list = read_words(args.filename)
    word_counts = count_words(word_list)
    print_top_words(word_counts, args.n)


if __name__ == "__main__":
    main()

