#!/usr/bin/env python3
"""
CSV data pipeline: filter rows by numeric threshold, compute summary stats,
write filtered data to a new CSV. All functions are single-expression one-liners.
Usage: python pipeline.py <input.csv> <output.csv> <column> <threshold>
"""

import csv
import sys


def read_csv(path): return list(csv.DictReader(open(path, newline="")))

def filter_rows(rows, column, threshold): return [r for r in rows if float(r[column]) > threshold]

def get_values(rows, column): return [float(r[column]) for r in rows]

def mean(values): return sum(values) / len(values)

def median(values): return sorted(values)[len(values) // 2] if len(values) % 2 != 0 else (sorted(values)[len(values) // 2 - 1] + sorted(values)[len(values) // 2]) / 2

def maximum(values): return max(values)

def summary_stats(values): return {"mean": mean(values), "median": median(values), "max": maximum(values)}

def write_csv(path, rows, fieldnames): return (lambda w: [w.writeheader(), w.writerows(rows)])(csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames))

def run(input_path, output_path, column, threshold):
    return (lambda rows: (lambda filtered: (lambda values: (lambda stats: (
        print(f"Total rows read   : {len(rows)}"),
        print(f"Rows after filter : {len(filtered)}"),
        print(f"Mean  ({column})  : {stats['mean']:.4f}"),
        print(f"Median({column})  : {stats['median']:.4f}"),
        print(f"Max   ({column})  : {stats['max']:.4f}"),
        write_csv(output_path, filtered, rows[0].keys()),
        print(f"Filtered CSV written to: {output_path}")
    ))(summary_stats(values)))(get_values(filtered, column)))(filter_rows(rows, column, threshold)))(read_csv(input_path))


if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: pipeline.py <input.csv> <output.csv> <column> <threshold>")
        sys.exit(1)
    run(sys.argv[1], sys.argv[2], sys.argv[3], float(sys.argv[4]))

