computes summary statistics, and writes filtered rows to a new CSV.

Usage:
    python csv_filter.py <input_file> <output_file> <column_name> <threshold>
"""

import csv
import sys
import statistics


def parse_arguments():
    if len(sys.argv) != 5:
        print(
            "Usage: python csv_filter.py <input_file> <output_file> <column_name> <threshold>",
            file=sys.stderr,
        )
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    column_name = sys.argv[3]

    try:
        threshold_value = float(sys.argv[4])
    except ValueError:
        print(f"Error: threshold must be a numeric value, got '{sys.argv[4]}'", file=sys.stderr)
        sys.exit(1)

    return input_file, output_file, column_name, threshold_value


def read_csv_file(input_file):
    try:
        with open(input_file, newline="", encoding="utf-8") as csv_file:
            reader = csv.DictReader(csv_file)
            rows = list(reader)
            field_names = reader.fieldnames
    except FileNotFoundError:
        print(f"Error: input file '{input_file}' not found.", file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f"Error reading '{input_file}': {exc}", file=sys.stderr)
        sys.exit(1)

    return rows, field_names


def validate_column(field_names, column_name):
    if field_names is None or column_name not in field_names:
        available = ", ".join(field_names) if field_names else "(none)"
        print(
            f"Error: column '{column_name}' not found. Available columns: {available}",
            file=sys.stderr,
        )
        sys.exit(1)


def parse_numeric_column(rows, column_name):
    numeric_values = []
    skipped_count = 0

    for row in rows:
        raw_value = row[column_name].strip()
        try:
            numeric_values.append(float(raw_value))
        except ValueError:
            skipped_count += 1

    if skipped_count > 0:
        print(
            f"Warning: {skipped_count} row(s) skipped due to non-numeric values in '{column_name}'.",
            file=sys.stderr,
        )

    return numeric_values


def filter_rows(rows, column_name, threshold_value):
    filtered_rows = []

    for row in rows:
        raw_value = row[column_name].strip()
        try:
            numeric_value = float(raw_value)
            if numeric_value > threshold_value:
                filtered_rows.append(row)
        except ValueError:
            pass  # skip non-numeric rows silently (already warned above)

    return filtered_rows


def compute_summary_statistics(numeric_values):
    if not numeric_values:
        return None

    mean_value = sum(numeric_values) / len(numeric_values)
    max_value = max(numeric_values)

    sorted_values = sorted(numeric_values)
    count = len(sorted_values)
    mid = count // 2
    if count % 2 == 0:
        median_value = (sorted_values[mid - 1] + sorted_values[mid]) / 2
    else:
        median_value = sorted_values[mid]

    return {
        "count": len(numeric_values),
        "mean": mean_value,
        "median": median_value,
        "max": max_value,
    }


def print_summary_statistics(summary_stats, column_name, threshold_value, filtered_count):
    print(f"\n--- Summary Statistics for column '{column_name}' (all rows) ---")
    if summary_stats is None:
        print("  No numeric data found.")
    else:
        print(f"  Total numeric rows : {summary_stats['count']}")
        print(f"  Mean               : {summary_stats['mean']:.4f}")
        print(f"  Median             : {summary_stats['median']:.4f}")
        print(f"  Max                : {summary_stats['max']:.4f}")

    print(f"\n--- Filtering (column '{column_name}' > {threshold_value}) ---")
    print(f"  Rows passing filter: {filtered_count}")


def write_csv_file(output_file, field_names, filtered_rows):
    try:
        with open(output_file, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.DictWriter(csv_file, fieldnames=field_names)
            writer.writeheader()
            writer.writerows(filtered_rows)
    except OSError as exc:
        print(f"Error writing '{output_file}': {exc}", file=sys.stderr)
        sys.exit(1)


def main():
    input_file, output_file, column_name, threshold_value = parse_arguments()

    all_rows, field_names = read_csv_file(input_file)

    if not all_rows:
        print("Warning: input file has no data rows.", file=sys.stderr)

    validate_column(field_names, column_name)

    numeric_values = parse_numeric_column(all_rows, column_name)
    summary_stats = compute_summary_statistics(numeric_values)

    filtered_rows = filter_rows(all_rows, column_name, threshold_value)

    print_summary_statistics(summary_stats, column_name, threshold_value, len(filtered_rows))

    write_csv_file(output_file, field_names, filtered_rows)

    print(f"\nFiltered data written to '{output_file}'.")


if __name__ == "__main__":
    main()

