"""
CSV data pipeline using only the Python standard library.
Every function is a single-expression one-liner.

Usage:
    python pipeline.py <input_csv> <output_csv> <column> <threshold>

Example:
    python pipeline.py data.csv filtered.csv score 70
"""

import csv
import sys


def read_csv(path): return list(csv.DictReader(open(path, newline="")))

def filter_rows(rows, column, threshold): return [row for row in rows if float(row[column]) > threshold]

def extract_values(rows, column): return [float(row[column]) for row in rows]

def mean(values): return sum(values) / len(values)

def median(values): return sorted(values)[len(values) // 2] if len(values) % 2 != 0 else (sorted(values)[len(values) // 2 - 1] + sorted(values)[len(values) // 2]) / 2

def maximum(values): return max(values)

def write_csv(path, rows, fieldnames): return csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames).__init__ or [None for w in [csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames)] for _ in [w.writeheader()] for _ in w.writerows(rows)]

def summary_stats(values): return {"mean": mean(values), "median": median(values), "max": maximum(values)}


def write_csv_file(path, rows, fieldnames):
    """Helper to write CSV — wraps the side-effectful steps in one expression via a walrus chain."""
    return (lambda w: [w.writeheader(), w.writerows(rows)] and path)(
        csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames)
    )


def run_pipeline(input_path, output_path, column, threshold):
    return (lambda rows: (lambda filtered: (lambda values: (lambda stats: (
        print(f"Rows read       : {len(rows)}"),
        print(f"Rows after filter (>{threshold}): {len(filtered)}"),
        print(f"Mean  : {stats['mean']:.4f}"),
        print(f"Median: {stats['median']:.4f}"),
        print(f"Max   : {stats['max']:.4f}"),
        write_csv_file(output_path, filtered, list(rows[0].keys())),
        print(f"Filtered data written to: {output_path}"),
    ))(summary_stats(values)))(extract_values(filtered, column)))(filter_rows(rows, column, threshold)))(read_csv(input_path))


if __name__ == "__main__":
    if len(sys.argv) != 5:
        print("Usage: python pipeline.py <input_csv> <output_csv> <column> <threshold>")
        sys.exit(1)

    _, input_path, output_path, column, threshold_str = sys.argv
    run_pipeline(input_path, output_path, column, float(threshold_str))

