from fastapi import Depends, FastAPI, HTTPException, Request
from pydantic import BaseModel


@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.store = {}
    yield


app = FastAPI(lifespan=lifespan)


def get_store(request: Request) -> dict[str, Any]:
    return request.app.state.store


class ItemBody(BaseModel):
    value: Any


@app.get("/items")
def list_items(store: dict = Depends(get_store)) -> dict[str, Any]:
    return store


@app.get("/items/{key}")
def get_item(key: str, store: dict = Depends(get_store)) -> Any:
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    return {"key": key, "value": store[key]}


@app.put("/items/{key}", status_code=200)
def put_item(key: str, body: ItemBody, store: dict = Depends(get_store)) -> dict[str, Any]:
    store[key] = body.value
    return {"key": key, "value": store[key]}


@app.delete("/items/{key}", status_code=200)
def delete_item(key: str, store: dict = Depends(get_store)) -> dict[str, str]:
    if key not in store:
        raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
    del store[key]
    return {"deleted": key}

