import argparse
import re
import sys
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the top N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file to analyse")
    parser.add_argument(
        "n",
        type=int,
        nargs="?",
        default=10,
        help="Number of top words to display (default: 10)",
    )
    return parser.parse_args()


def count_words(text):
    words = re.findall(r"[a-z]+", text.lower())
    return Counter(words)


def read_file(filename):
    try:
        with open(filename, "r", encoding="utf-8") as fh:
            return fh.read()
    except FileNotFoundError:
        print(f"Error: file not found: {filename}", file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        sys.exit(1)


def print_top_words(counter, n):
    for word, count in counter.most_common(n):
        print(f"{word}: {count}")


def main():
    args = parse_args()
    text = read_file(args.filename)
    counter = count_words(text)
    print_top_words(counter, args.n)


if __name__ == "__main__":
    main()

