"""
CSV data pipeline: filter rows by numeric threshold, compute summary stats,
write filtered data to output CSV.

Usage: python pipeline.py input.csv output.csv column_name threshold
"""

import csv
import statistics
import sys

EXIT_BAD_ARGS = 2
EXIT_IO_ERROR = 3
EXIT_DATA_ERROR = 4


def parse_args(argv: list[str]) -> tuple[str, str, str, float]:
    if len(argv) != 5:
        print(
            "Usage: pipeline.py input.csv output.csv column_name threshold",
            file=sys.stderr,
        )
        sys.exit(EXIT_BAD_ARGS)

    input_path, output_path, column_name, threshold_str = argv[1], argv[2], argv[3], argv[4]

    try:
        threshold = float(threshold_str)
    except ValueError:
        print(f"Error: threshold must be a number, got '{threshold_str}'", file=sys.stderr)
        sys.exit(EXIT_BAD_ARGS)

