from fastapi import FastAPI, HTTPException, Depends, Request
from pydantic import BaseModel


class ValuePayload(BaseModel):
    value: str


def create_app() -> FastAPI:
    app = FastAPI()
    app.state.store = {}

    def get_store(request: Request) -> dict:
        return request.app.state.store

    @app.get("/items")
    def list_items(store: dict = Depends(get_store)):
        return store

    @app.get("/items/{key}")
    def get_item(key: str, store: dict = Depends(get_store)):
        if key not in store:
            raise HTTPException(status_code=404, detail="Key not found")
        return {"key": key, "value": store[key]}

    @app.put("/items/{key}")
    def put_item(key: str, payload: ValuePayload, store: dict = Depends(get_store)):
        store[key] = payload.value
        return {"key": key, "value": store[key]}

    @app.delete("/items/{key}")
    def delete_item(key: str, store: dict = Depends(get_store)):
        if key not in store:
            raise HTTPException(status_code=404, detail="Key not found")
        del store[key]
        return {"detail": "Deleted"}

    return app


app = create_app()

