import argparse
import re
from collections import Counter


def parse_args():
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def count_words(filename):
    with open(filename, "r", encoding="utf-8") as f:
        text = f.read().lower()
    words = re.findall(r"[a-z]+", text)
    return Counter(words)


def main():
    args = parse_args()
    counts = count_words(args.filename)
    for word, freq in counts.most_common(args.n):
        print(f"{word}: {freq}")


if __name__ == "__main__":
    main()

