import argparse
import re
import sys
from collections import Counter


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def count_words(text: str) -> Counter:
    words = re.findall(r"[a-zA-Z']+", text.lower())
    return Counter(words)


def main() -> None:
    args = parse_args()

    if args.n <= 0:
        print("Error: N must be a positive integer.", file=sys.stderr)
        sys.exit(1)

    try:
        with open(args.filename, encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        print(f"Error: file not found: {args.filename}", file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        sys.exit(1)

    counts = count_words(text)
    if not counts:
        print("No words found in the file.")
        return

    top_n = counts.most_common(args.n)
    width = max(len(word) for word, _ in top_n)
    for word, count in top_n:
        print(f"{word:<{width}}  {count}")


if __name__ == "__main__":
    main()

