import csv
import sys


def read_csv(path): return list(csv.DictReader(open(path, newline="")))

def filter_rows(rows, column, threshold): return [r for r in rows if float(r[column]) > threshold]

def get_values(rows, column): return [float(r[column]) for r in rows]

def mean(values): return sum(values) / len(values)

def median(values): return sorted(values)[len(values) // 2] if len(values) % 2 != 0 else (sorted(values)[len(values) // 2 - 1] + sorted(values)[len(values) // 2]) / 2

def maximum(values): return max(values)

def write_csv(path, rows, fieldnames): return csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames).writerows(rows) or (lambda w: [w.writeheader(), w.writerows(rows)])(csv.DictWriter(open(path, "w", newline=""), fieldnames=fieldnames))

