from fastapi import FastAPI, Depends, HTTPException
from pydantic import BaseModel
from typing import Any


class Store:
    def __init__(self) -> None:
        self._data: dict[str, Any] = {}

    def get(self, key: str) -> Any:
        return self._data.get(key)

    def set(self, key: str, value: Any) -> None:
        self._data[key] = value

    def delete(self, key: str) -> bool:
        if key not in self._data:
            return False
        del self._data[key]
        return True

    def all(self) -> dict[str, Any]:
        return dict(self._data)


class PutBody(BaseModel):
    value: Any


def make_app() -> FastAPI:
    app = FastAPI()
    store = Store()

    def get_store() -> Store:
        return store

    @app.get("/items")
    def list_items(s: Store = Depends(get_store)) -> dict[str, Any]:
        return s.all()

    @app.get("/items/{key}")
    def get_item(key: str, s: Store = Depends(get_store)) -> Any:
        value = s.get(key)
        if value is None and key not in s.all():
            raise HTTPException(status_code=404, detail="Key not found")
        return {"key": key, "value": value}

    @app.put("/items/{key}", status_code=200)
    def put_item(key: str, body: PutBody, s: Store = Depends(get_store)) -> dict[str, Any]:
        s.set(key, body.value)
        return {"key": key, "value": body.value}

    @app.delete("/items/{key}", status_code=200)
    def delete_item(key: str, s: Store = Depends(get_store)) -> dict[str, str]:
        if not s.delete(key):
            raise HTTPException(status_code=404, detail="Key not found")
        return {"deleted": key}

    return app


app = make_app()

