#!/usr/bin/env python3
"""Console utility to find the N most frequent words in a text file."""

import argparse
import re
from collections import Counter


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Print the N most frequent words in a text file."
    )
    parser.add_argument("filename", help="Path to the text file to analyze")
    parser.add_argument("n", type=int, help="Number of top words to display")
    return parser.parse_args()


def read_words(filename: str) -> list[str]:
    with open(filename, encoding="utf-8") as f:
        text = f.read()
    return re.findall(r"[a-zA-Z']+", text.lower())


def top_words(words: list[str], n: int) -> list[tuple[str, int]]:
    return Counter(words).most_common(n)


def main() -> None:
    args = parse_args()
    words = read_words(args.filename)
    for word, count in top_words(words, args.n):
        print(f"{word} {count}")


if __name__ == "__main__":
    main()

