"""
CSV pipeline: filter rows by numeric threshold and compute summary statistics.
Usage: python pipeline.py <input_csv> <output_csv> <column> <threshold>
"""

import argparse
import csv
import statistics
import sys


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows by numeric threshold and report statistics."
    )
    parser.add_argument("input_file", help="Path to the input CSV file")
    parser.add_argument("output_file", help="Path to the output CSV file")
    parser.add_argument("column", help="Name of the numeric column to filter on")
    parser.add_argument("threshold", type=float, help="Keep rows where column > threshold")
    return parser.parse_args(argv)


def read_csv(path: str) -> tuple[list[str], list[dict[str, str]]]:
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        if reader.fieldnames is None:
            return [], []
        fieldnames = list(reader.fieldnames)
        rows = list(reader)
    return fieldnames, rows


def filter_rows(
    rows: list[dict[str, str]], column: str, threshold: float
) -> tuple[list[dict[str, str]], list[float]]:
    filtered: list[dict[str, str]] = []
    values: list[float] = []
    for row in rows:
        raw = row.get(column)
        if raw is None:
            continue
        try:
            value = float(raw)
        except ValueError:
            continue
        if value > threshold:
            filtered.append(row)
            values.append(value)
    return filtered, values


def compute_statistics(values: list[float]) -> dict[str, float]:
    if not values:
        return {}
    return {
        "mean": statistics.mean(values),
        "median": statistics.median(values),
        "max": max(values),
    }


def write_csv(path: str, fieldnames: list[str], rows: list[dict[str, str]]) -> None:
    with open(path, "w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)

    fieldnames, rows = read_csv(args.input_file)
    if not fieldnames:
        print("Error: input file is empty or has no headers.", file=sys.stderr)
        return 1

    if args.column not in fieldnames:
        print(
            f"Error: column '{args.column}' not found. Available: {fieldnames}",
            file=sys.stderr,
        )
        return 1

    filtered_rows, values = filter_rows(rows, args.column, args.threshold)

    stats = compute_statistics(values)
    if stats:
        print(f"Rows passing filter (>{args.threshold}): {len(filtered_rows)}")
        print(f"  mean   = {stats['mean']:.4f}")
        print(f"  median = {stats['median']:.4f}")
        print(f"  max    = {stats['max']:.4f}")
    else:
        print("No rows passed the filter — no statistics to report.")

    write_csv(args.output_file, fieldnames, filtered_rows)
    print(f"Filtered data written to: {args.output_file}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

