    return sorted(float(r[column]) for r in rows)[len(rows) // 2] if len(rows) % 2 != 0 else (sorted(float(r[column]) for r in rows)[len(rows) // 2 - 1] + sorted(float(r[column]) for r in rows)[len(rows) // 2]) / 2


