    output_path = sys.argv[2] if len(sys.argv) > 2 else "output.csv"
    column = sys.argv[3] if len(sys.argv) > 3 else "score"
    threshold = float(sys.argv[4]) if len(sys.argv) > 4 else 60.0

    rows = read_csv(input_path)
    filtered = filter_rows(rows, column, threshold)
    stats = summary_stats(filtered, column)
    write_csv(filtered, output_path)

    print(f"Input rows   : {len(rows)}")
    print(f"Filtered rows: {len(filtered)}  ('{column}' > {threshold})")
    print(f"Mean         : {stats['mean']:.2f}")
    print(f"Median       : {stats['median']:.2f}")
    print(f"Max          : {stats['max']:.2f}")
    print(f"Output written to: {output_path}")

