class ValueBody(BaseModel):
    value: Any


def create_app() -> FastAPI:
    application = FastAPI(title="Key-Value Store")
    application.state.store = {}

    def get_store() -> dict:
        return application.state.store

    @application.get("/items")
    def list_items(store: dict = Depends(get_store)) -> dict:
        return store

    @application.get("/items/{key}")
    def get_item(key: str, store: dict = Depends(get_store)) -> Any:
        if key not in store:
            raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
        return {"key": key, "value": store[key]}

    @application.put("/items/{key}", status_code=200)
    def put_item(key: str, body: ValueBody, store: dict = Depends(get_store)) -> dict:
        store[key] = body.value
        return {"key": key, "value": store[key]}

    @application.delete("/items/{key}", status_code=200)
    def delete_item(key: str, store: dict = Depends(get_store)) -> dict:
        if key not in store:
            raise HTTPException(status_code=404, detail=f"Key '{key}' not found")
        del store[key]
        return {"deleted": key}

    return application


app = create_app()

